pub fn p4_fragment_for_column(col: u32) -> String {
    let tags = tags_for_column(col);
    if tags.is_empty() {
        String::new()
    } else {
        tags.iter()
            .map(|v| v.to_string())
            .collect::<Vec<_>>()
            .join(",")
    }
}
